/// <summary>
/// designed fron AVAFRN
/// </summary>
public void postBuild()
{
    super();

    dataContract = this.dataContractObject();

    masterQuotationField   = this.bindInfo().getDialogField(dataContract, methodstr(AVACalcSalesQuotationLineMasterPriceContract, parmMasterQuotationId));

    masterQuotationField.registerOverrideMethod(methodstr(FormStringControl, lookUp), methodstr(AVACalcSalesQuotationLineMasterPriceUIBuilder, masterQuotationlookup), this);
}

/// <summary>
/// designed from AVAFRN
/// </summary>
/// <param name = "_formControl">formLookup</param>

private void masterQuotationlookup(FormControl _formControl)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(SalesQuotationTable),_formControl);
    Query                   query = new Query();
    QueryBuildDataSource    salesQuotationTableDS;
    SalesQuotationTable     salesQuotationTable = SalesQuotationTable::find(dataContract.parmQuotationId());

    salesQuotationTableDS = query.addDataSource(tableNum(SalesQuotationTable));
    salesQuotationTableDS.addRange(fieldNum(SalesQuotationTable,CurrencyCode)).value(salesQuotationTable.CurrencyCode);

    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,QuotationId),true);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,CustAccount),false);
    sysTableLookup.addLookupfield (fieldNum(SalesQuotationTable,BusRelAccount),false);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,KCS_KBVRequestId),false);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,KCS_KBVBuildingProjectID),false);

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
